import pandas as pd
d=pd.read_csv('responses.csv'); print(len(d), d.number_set.nunique())
def rules(xs):
    out=[]
    if all(x%2 for x in xs): out.append(2)
    for k in range(2,13):
        if all(x%k==0 for x in xs): out.append(('m',k))
    return out
g=d.groupby(['number_set','target']).rating.agg(['mean','count']).reset_index()
for s,gg in g.groupby('number_set'):
    xs=[int(v) for v in s.split(',')]
    if len(xs)<2: continue
    r=rules(xs)
    if not r: continue
    lo,hi=min(xs),max(xs)
    def mem(t):
        return any((t%2==1) if q==2 else t%q[1]==0 for q in r)
    ins=gg[(gg.target>lo)&(gg.target<hi)&~gg.target.apply(mem)]
    outm=gg[((gg.target<lo)|(gg.target>hi))&gg.target.apply(mem)]
    print(s, hi-lo, r[:3], 'inNM', ins['mean'].round(2).tolist(), list(ins.target), '| outM', outm['mean'].round(2).tolist())
"

