import numpy as np, pandas as pd
d=pd.read_csv('responses.csv')
P={k:np.load(f'/tmp/p_{k}.npy') for k in ['range_limited_rule_familiar_strays','candidate_2','cluster_cued_range_salience']}
for a in P:
  for b in P:
    if a<b: print(a,b,np.sqrt(np.mean((P[a]-P[b])**2)).round(4))
# critique stat
def rules(xs):
    r=[]
    if all(x%2 for x in xs): r.append(lambda t:t%2==1)
    for k in range(2,13):
        if all(x%k==0 for x in xs): r.append(lambda t,k=k:t%k==0)
    return r
mask=[]
for s,t in zip(d.number_set,d.target):
    xs=[int(v) for v in s.split(',')]; r=rules(xs)
    ok=len(xs)>1 and r and max(xs)-min(xs)<=40 and min(xs)<t<max(xs) and not any(f(t) for f in r)
    mask.append(bool(ok))
mask=np.array(mask); print('n',mask.sum(),'obs',d.rating[mask].mean().round(3), {k:v[mask].mean().round(3) for k,v in P.items()})
EOF

